func normalizeRunSubcommand(args []string) (bool, []string) {
	if len(args) == 0 {
		return false, args
	}
	boolFlags := map[string]bool{
		"allow-deprecated-model": true,
		"json":                   true,
		"list-models":            true,
		"plan":                   true,
		"version":                true,
	}
	valueFlags := map[string]bool{
		"backend":   true,
		"harness":   true,
		"max-power": true,
		"max-iter":  true,
		"min-power": true,
		"model":     true,
		"model-ref": true,
		"p":         true,
		"preset":    true,
		"provider":  true,
		"reasoning": true,
		"system":    true,
		"work-dir":  true,
	}

	for i := 0; i < len(args); i++ {
		arg := args[i]
		switch {
		case arg == "run":
			out := append([]string{}, args[:i]...)
			out = append(out, args[i+1:]...)
			return true, out
		case strings.HasPrefix(arg, "-"):
			flagName := strings.TrimLeft(arg, "-")
			if boolFlags[flagName] {
				continue
			}
			if valueFlags[flagName] && i+1 < len(args) {
				i++
			}
		default:
			return false, args
		}
	}

	return false, args
}

